export function loadThemeCss(id: number): Promise<string> {
  const loader = THEME_CSS_LOADERS[id]
  if (!loader) {
    return Promise.reject(new Error(`Theme CSS not found: ${id}`))
  }

  return loader().then((cssModule) => cssModule.default)
}
